import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.CZxGLIO_.js";const u=JSON.parse('{"title":"Rooster","description":"Practical Rooster guides.","frontmatter":{"title":"Rooster","description":"Practical Rooster guides."},"headers":[],"relativePath":"en/docs/rooster/index.md","filePath":"en/docs/rooster/index.md"}'),n={name:"en/docs/rooster/index.md"};function d(s,e,i,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rooster" tabindex="-1">Rooster <a class="header-anchor" href="#rooster" aria-label="Permalink to &quot;Rooster&quot;">​</a></h1><p>Rooster combines a local web console, native tray, SQLite execution history and process management. Use it for development services, long-running workers and periodic scripts, with a local HTTP API for agents.</p><p>Checked against commit <strong>96c86ae</strong> on 2026-11-15. There are no published GitHub Releases at this date. Older source builds may lack backup and retention endpoints; read <code>/api/docs</code> from the running instance.</p><h2 id="reading-path" tabindex="-1">Reading path <a class="header-anchor" href="#reading-path" aria-label="Permalink to &quot;Reading path&quot;">​</a></h2><p>Start with installation, create a disabled <code>echo ready</code> task, run it manually and inspect history and logs. Enable automation only after verifying the result, then set up backups. The service has no remote authentication layer and should stay local.</p><table tabindex="0"><thead><tr><th>Guide</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./installation/">Installation and runtime</a></td><td>Daemon, tray, packaging and isolated data</td></tr><tr><td><a href="./tasks/">Task configuration and execution</a></td><td>Command modes, Cron, restarts and concurrency</td></tr><tr><td><a href="./agent-api/">Agents and HTTP API</a></td><td>Create, run, inspect results and handle errors</td></tr><tr><td><a href="./maintenance/">Backup, recovery and logs</a></td><td>Online snapshots, offline recovery, logs and cleanup</td></tr><tr><td><a href="./troubleshooting/">Troubleshooting</a></td><td>Ports, environment, task state and recovery</td></tr></tbody></table><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/README.md" target="_blank" rel="noreferrer">README</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">API</a>。</p>',8)])])}const b=t(n,[["render",d]]);export{u as __pageData,b as default};
